import sys, heapq
from collections import defaultdict

def bags(s):
    n,k=map(int,s.split()); M=10**9+7
    dp=[1]+[0]*k
    for i in range(1,n+1):
        for j in range(min(i,k),0,-1): dp[j]=(j*dp[j]+dp[j-1])%M
        dp[0]=0
    return str(dp[k])

print(bags(sys.stdin.read()))

